#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using ld = long double;

#define all(a) a.begin(), a.end()
#define rall(a) a.rbegin(), a.rend()
#define rep(i, n) for(int i = 0; i < (n); i += 1)
#define len(a) ((int)(a).size())

const ll inf = 1e18;
mt19937 rnd(234);

struct SegTree {
    int len;
    vector <multiset <int>> t;
    vector <int> a;

    SegTree(int n, const vector <int>& a) : a(a) {
        len = 1 << (int)ceil(log2(n));
        t.resize(2 * len);
        build(1, 0, len - 1);
    }

    void build(int v, int l, int r) {
        if (l == r) {
            if (l < a.size()) t[v].insert(a[l]);
            else t[v].insert(1);
            return;
        }
        int m = (l + r) / 2;
        build(2 * v, l, m);
        build(2 * v + 1, m + 1, r);
        for (auto i : t[2 * v]) t[v].insert(i);
        for (auto i : t[2 * v + 1]) t[v].insert(i);
    }

    int max_less_or_eq(int v, int l, int r, int A, int B, int x) {
        if (l > B || A > r) return -1;
        if (A <= l && r <= B) {
            auto it = t[v].upper_bound(x);
            if (it != t[v].begin()) return *prev(it);
            return -1;
        }
        int m = (l + r) / 2;
        return max(max_less_or_eq(2 * v, l, m, A, B, x), max_less_or_eq(2 * v + 1, m + 1, r, A, B, x));
    }

    int max_less_or_eq(int l, int r, int x) {
        return max_less_or_eq(1, 0, len - 1, l, r, x);
    }

    void update(int v, int l, int r, int i, int was_val, int new_val) {
        if (l > i || i > r) return;
        t[v].erase(t[v].find(was_val));
        t[v].insert(new_val);
        if (l == r) return;
        int m = (l + r) / 2;
        update(2 * v, l, m, i, was_val, new_val);
        update(2 * v + 1, m + 1, r, i, was_val, new_val);
    }

    inline void update(int i, int new_val) {
        update(1, 0, len - 1, i, a[i], new_val);
        a[i] = new_val;
    }
};
inline void solve() {
    int n, q;
    cin >> n >> q;
    vector <int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    SegTree t(n, a);
    while (q--) {
        int type;
        cin >> type;
        if (type == 1) {
            int i, x;
            cin >> i >> x;
            t.update(i - 1, x);
        }
        else {
            int l, r, s;
            cin >> l >> r >> s; --l; --r;

            while (true) {
                int x = t.max_less_or_eq(l, r, s);
                if (x == -1) break;
                s %= x;
            }

            cout << s << "\n";
        }
    }
}

int32_t main() {
    if (1) {
        ios::sync_with_stdio(0);
        cin.tie(0);
        cout.tie(0);
    }
    int t = 1;
    // cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}
